BASE=Path(__file__).resolve().parents[1]
OUT=BASE/'.cache/batch200/drafts/rewrite_spec';OUT.mkdir(parents=True,exist_ok=True)
O=[['拉丁 opus〔属格 operis〕／opera','工作、劳动；做成的作品']]
ACT=O+[['拉丁 operārī，分词词干 operāt-','做事、起作用'],['英语 operate','有拉丁分词借入及从 operation 逆构两种分析']]
ION=O+[['拉丁 operārī → operātiō','做事 → 做事的过程'],['古法语 operacion → 中古英语 operacioun → 英语 operation','运行、行动；后来用于手术等有组织的操作']]
IVE=O+[['拉丁 operārī → 中世纪拉丁 operātīvus','工作、产生作用的'],['法语 operatif 及拉丁来源 → 中古英语 operative → 英语 operative','起作用的；后来也作名词指工作人员']]
ABLE=O+[['拉丁 operārī → 后期拉丁 operābilis；或英语 operate + -able','拉丁形容词借入与英语派生两种分析'],['英语 operable','可以运作或使用的；可用手术治疗的']]
CO=O+[['后期拉丁 co- + operārī → cooperārī','一同工作'],['后期拉丁 cooperātus → 英语 cooperate','一起做事、相互配合']]
COIVE=CO[:-1]+[['拉丁分词词干 cooperāt- + -ive；也可按 co- + operative 分析','共同起作用的'],['英语 cooperative','合作的、配合的；后来作名词指合作组织']]
OPERA=O+[['意大利 opera','拉丁复数形式被作为阴性单数使用；作品'],['英语 opera〔借自意大利语〕','以音乐和歌唱展开戏剧的歌剧']]
W=[
E('operation','英 /ˌɒpəˈreɪʃən/；美 /ˌɑːpəˈreɪʃən/','运行；操作；行动；手术；运算','让一件事按一套步骤真正做起来。','现代可对应 operate + -ion，但名词经法语独立借自拉丁 operātiō，英语里比 operate 更早，不能倒画成只有英语动词派生。',ION,'机器 in operation 是正在运转；rescue operation 是有组织的救援行动；an operation on a knee 是膝部手术。数学的 operation 则把输入按规则变成结果，比如相加。几个意思共同强调“执行一套动作”。','in operation；a rescue operation；have an operation；the operation of a machine。','process 强调过程怎样展开；operation 常强调一项有目的的运作、行动或操作。不是每个 operation 都是手术。',('The new water pump is now in operation.','新的水泵现已投入运行。'),('The rescue operation continued through the night.','救援行动持续了一整夜。'),('She had an operation on her knee last month.','她上个月做了膝部手术。')),
E('operate','英 /ˈɒpəreɪt/；美 /ˈɑːpəreɪt/','操作；运转；经营；动手术','让机器、业务或一套工作真正动起来；也可以是它自己在运作。','来源有拉丁 operātus 分词词干借入，以及从较早的 operation 逆构两说；远接 operārī“做事”。',ACT,'operate a machine 是人操作机器；the machine operates quietly 是机器运行得安静。医疗用法一般说 operate on a patient，不直接用 operate a patient。公司 operate in several cities，则是业务在这些城市开展。','operate machinery；operate in a market；operate on a patient；operate smoothly。','run 很口语，可广泛说机器运行或经营；operate 更常见于设备、制度、业务和专业程序。',('Only trained staff may operate this lift.','只有受过培训的员工可以操作这台升降机。'),('The company operates in six countries.','这家公司在六个国家开展业务。'),('The surgeon will operate on her shoulder tomorrow.','外科医生明天将为她做肩部手术。'),sources=['https://www.etymonline.com/word/operate']),
E('operator','英 /ˈɒpəreɪtə/；美 /ˈɑːpəreɪtər/','操作员；运营商；算符；精于办事的人','掌握控制或执行规则，让一套东西运行起来的那一方。','借自拉丁 operātor“工作者”，接 operārī；现代可看成 operate + -or，但历史上名词有自己的借入路线。',O+[['拉丁 operārī → operātor','做事 → 做事的人'],['英语 operator','操作设备或经营服务的人、机构；后来用于数学和计算机']],'电话 operator 原来替用户接线；bus operator 可以是运营公交的公司。程序中的 + 是一种 operator，指定对两边的数做什么。a smooth operator 则形容很会办事、周旋的人，可能略带警惕。','a machine operator；a tour operator；a network operator；a mathematical operator。','operation 是做的事或运行过程；operator 是执行者，也可以是规定运算的符号或映射。',('The crane operator waited for a signal before lifting the load.','起重机操作员等到信号后才吊起重物。'),('The tour operator arranged transport between the two islands.','旅游运营商安排了两座岛之间的交通。'),sources=['https://en.wiktionary.org/wiki/operator#English']),
E('cooperation','英 /kəʊˌɒpəˈreɪʃən/；美 /koʊˌɑːpəˈreɪʃən/','合作；配合；协作','各方的动作能接得上，一起把同一件事往前推。','经法语 coopération 或直接借后期拉丁 cooperātiō；现代可对应 cooperate + -ion，不等于历史上只能由英语动词派生。',CO[:-1]+[['后期拉丁 cooperātiō → 法语 coopération／直接借入路线','共同工作的过程'],['英语 cooperation','合作与配合']],'国际合作可以是共同研发；Thank you for your cooperation 也可能只是感谢你按要求排队、提供资料。重点是参与和配合，不要求大家成为朋友，也不要求共同拥有一个公司。','cooperation between teams；in cooperation with；international cooperation。','collaboration 常强调共同完成具体作品或项目；cooperation 还可指较宽泛的相互支持、配合。',('The bridge project depends on cooperation between the two towns.','建桥项目有赖于两座城镇之间的合作。'),('Thank you for your cooperation during the safety inspection.','感谢大家在安全检查期间的配合。'),sources=['https://www.etymonline.com/word/cooperation']),
E('opera','英 /ˈɒpərə/；美 /ˈɑːpərə/','歌剧；歌剧艺术','本来只是“作品”，后来专指用音乐和歌唱把戏剧演出来的一类作品。','借自意大利 opera；其远源是拉丁 opus 的复数 opera，后来被当作阴性单数名词使用。英语 opera 是单数，复数通常加 -s 成 operas。',OPERA,'歌剧结合人物、剧情、音乐和舞台表演，不是独唱歌曲的总称。它与 operate 的联系在更早的“做事、作品”层面；现代 opera 不是把 operate 去掉 -te。','an opera singer；an opera house；perform an opera；Italian opera。','musical 通常译音乐剧，和 opera 都用音乐讲故事，但属于不同表演传统，不能只凭是否有对白划死界线。',('This opera tells the story of two families divided by a feud.','这部歌剧讲述两个家族因世仇而分裂的故事。'),('She began studying opera after several years of choral singing.','唱了几年合唱后，她开始学习歌剧。'),sources=['https://www.etymonline.com/word/opera']),
E('cooperate','英 /kəʊˈɒpəreɪt/；美 /koʊˈɑːpəreɪt/','合作；配合','你做的和我做的能够相互接上，而不是各自抵消。','后期拉丁 cooperārī 的分词 cooperātus 进入英语；co- 表示共同，现代也可看作 co- + operate。',CO,'cooperate with someone 是与谁合作；cooperate on a project 是在什么事上合作。一个人愿意提供信息也可以叫 cooperate，不必参与整项工程。口语里还会说天气或机器不配合。','cooperate with colleagues；cooperate on a project；cooperate fully。','comply 更偏遵守要求；cooperate 可以是平等协作，也可以是配合调查，不必总有命令关系。',('The two laboratories agreed to cooperate on the study.','两家实验室同意合作开展这项研究。'),('The witness cooperated with the investigators and answered their questions.','证人配合调查人员，回答了他们的问题。')),
E('opus','英 /ˈəʊpəs/；美 /ˈoʊpəs/','作品；编号的音乐作品','把劳动凝成一个可以指认的成果：这是一部作品。','直接借拉丁 opus“工作、作品”；属格 operis 显示与 oper- 一族的联系。不是英语 opera 的缩略。',O+[['英语 opus〔直接借拉丁语〕','正式谈艺术作品；音乐中常配作品编号']],'乐谱上的 Op. 是 opus 的缩写，后面跟作品编号；一个编号有时涵盖一组作品，不能机械理解成作曲家人生中写的第几首。magnum opus 是某人的代表性巨作。','Op. 12；a major opus；someone’s magnum opus。','opus 常指一部或一组作品；oeuvre 常指一位创作者整体的作品。作品编号不保证严格按创作日期排序。',('The programme lists the quartet as Op. 12.','节目单把这首四重奏列为作品第十二号。'),('The critic described the novel as the author’s magnum opus.','评论家把这部小说称为作者的代表巨作。'),sources=['https://www.etymonline.com/word/opus']),
E('operatic','英 /ˌɒpəˈrætɪk/；美 /ˌɑːpəˈrætɪk/','歌剧的；像歌剧般夸张的','属于歌剧的声音或表演方式，也可比喻情绪起伏很大、场面很戏剧化。','opera + -ic 的派生受 dramatic 的形式影响，形成 -atic；不是从 operate“操作”派生。',OPERA+[['英语 opera → operatic〔受 dramatic 形式影响〕','与歌剧有关的；歌剧般强烈的']],'operatic training 是歌剧演唱训练。把一次普通争吵说成 operatic，通常是觉得它的情绪、姿态和场面像舞台大戏。','an operatic voice；an operatic role；operatic intensity。','operative 是起作用的或手术的；operatic 是歌剧的，拼写只差一点，意思却走了不同分支。',('Her operatic training gives her voice unusual power.','歌剧训练让她的声音格外有力量。'),('The film ends with an argument of almost operatic intensity.','电影以一场情绪强烈得近乎歌剧的争吵结束。'),sources=['https://www.etymonline.com/word/operatic']),
E('inoperable','英 /ɪnˈɒpərəbəl/；美 /ɪnˈɑːpərəbəl/','无法使用的；不能用手术治疗的','本来可以靠操作去完成的事，现在这条路走不通。','in-“不” + operable“能使用或能手术的”；这里 in- 是否定，不是“在里面”。',ABLE+[['英语 in- + operable → inoperable','不能运行、使用；或无法用手术治疗']],'inoperable equipment 是不能用的设备。医学里的 inoperable 指无法用手术治疗，不自动等于所有治疗都无效。究竟为何不能手术，是另一个具体问题，词本身没有全部说明。','an inoperable device；an inoperable tumour；render something inoperable。','inoperative 多说当前不工作、不生效；inoperable 更强调无法操作或使用，医学中尤其指手术这条途径不可行。',('Water damage left the old control panel inoperable.','进水损坏使旧控制面板无法使用。'),('The report described the tumour as inoperable and listed other treatment options.','报告称该肿瘤无法手术，并列出了其他治疗方案。'),sources=['https://www.cancer.gov/publications/dictionaries/cancer-terms/def/inoperable','https://www.etymonline.com/word/inoperable']),
E('operable','英 /ˈɒpərəbəl/；美 /ˈɑːpərəbəl/','可运行的；可使用的；可手术治疗的','设备能被用起来；病情也可以指有手术处理的可能。','有后期拉丁 operābilis 借入和英语 operate + -able 两种分析。现代 -able 很直观地表达“能够”。',ABLE,'窗户 operable 表示能打开、关闭，不只是固定玻璃。operable tumour 指可以手术处理的肿瘤；这个词没有承诺手术一定成功。','remain operable；an operable window；an operable tumour。','operable 强调能够使用；operational 常强调已准备好或已投入运行。设备可操作，不代表整个系统已经上线。',('All emergency doors must remain operable during opening hours.','营业期间，所有应急门都必须保持可以开启。'),('The surgeon explained why the tumour was considered operable.','外科医生解释了为什么判断该肿瘤可以手术治疗。'),sources=['https://www.etymonline.com/word/operable']),
E('operational','英 /ˌɒpəˈreɪʃənəl/；美 /ˌɑːpəˈreɪʃənəl/','运行的；业务操作的；可投入使用的','从纸上的计划走到实际运行：人、设备和步骤都能够开始做事。','operation + -al；这里的 operation 可以是系统运行、日常业务或军事行动。',ION+[['英语 operation + -al → operational','涉及实际运作；已经能运行']],'fully operational 是系统已可正常使用。operational costs 是维持实际运作的成本。研究里 operational definition 则把抽象概念换成可执行的观察或测量规则，例如“用哪项指标算作进步”。','fully operational；operational costs；an operational plan；an operational definition。','strategic 关心总体方向；operational 常关心怎样把日常运行或具体行动落实。',('The new booking system will be fully operational on Monday.','新的预订系统将在周一全面投入运行。'),('The report separates construction costs from operational costs.','报告把建设成本与运营成本分开列出。')),
E('operative','英 /ˈɒpərətɪv/；美 /ˈɑːpərətɪv/','生效的；起作用的；手术的；工作人员；特工','真正参与行动、产生效果的那一部分。','经法语 operatif 及拉丁 operātīvus 借入；现代可与 operate + -ive 对照。名词是形容词转用，指干这项工作的人。',IVE,'an operative rule 是正在起作用的规则；the operative word 是整句话里真正要抓住的关键词。医学中 operative treatment 指手术治疗；名词 a factory operative 是生产人员，an intelligence operative 则是情报人员。','become operative；the operative word；operative treatment；an intelligence operative。','operative 与 operational 都可说有效运作；operative 还常指具体生效条文、关键词或行动人员。',('The new restrictions become operative next month.','新限制下个月生效。'),('In “temporary accommodation”, temporary is the operative word.','在“临时住所”里，真正要抓住的词是“临时”。'),('The novel follows an intelligence operative working abroad.','这部小说讲述一名在海外工作的情报人员的经历。'),sources=['https://www.etymonline.com/word/operative']),
E('cooperative','英 /kəʊˈɒpərətɪv/；美 /koʊˈɑːpərətɪv/','愿意配合的；合作的；合作社','各方愿意一起使劲；作为组织，则是成员共同参与经营和所有权。','可按 co- + operative 理解；另一来源分析接后期拉丁 cooperāt- 加 -ive。名词由形容词转用，表示合作经营的组织。',COIVE,'a cooperative person 容易配合，不处处设障碍。a cooperative 是成员共同拥有、按合作方式治理的企业，例如消费者、农民或员工的合作社；并不是所有“同事合作愉快”的公司都叫这个。','a cooperative attitude；cooperative learning；a workers’ cooperative。','cooperative 描述配合态度或合作性质；a cooperative 另有具体组织含义，需要按名词读。',('The neighbours were cooperative while the road was being repaired.','修路期间，邻居们都很配合。'),('The farmers formed a cooperative to sell their produce together.','农民们成立了合作社，一起销售农产品。'),sources=['https://www.etymonline.com/word/cooperative','https://en.wiktionary.org/wiki/cooperative#English']),
E('cooperatively','英 /kəʊˈɒpərətɪvli/；美 /koʊˈɑːpərətɪvli/','合作地；配合地','做事时把别人的动作考虑进去，让各自的一部分合起来。','cooperative + -ly；修饰工作的方式或组织的经营方式。',COIVE+[['英语 cooperative + -ly → cooperatively','以协作、配合的方式']],'work cooperatively 是一起配合完成工作；cooperatively owned 则说所有权采取合作社方式。不能只译成“态度友好”，因为它还涉及实际怎样组织行动。','work cooperatively；solve a problem cooperatively；cooperatively owned。','collectively 强调作为一个整体；cooperatively 更强调成员互相配合的方式。',('The children worked cooperatively to build a bridge from cardboard.','孩子们相互配合，用纸板搭了一座桥。'),('The shop is cooperatively owned by local producers.','这家店由当地生产者以合作社方式共同拥有。')),
E('uncooperative','英 /ˌʌnkəʊˈɒpərətɪv/；美 /ˌʌnkoʊˈɑːpərətɪv/','不配合的；不愿合作的','需要各方把动作接起来时，有一方不肯参与或总是阻碍。','un-“不” + cooperative；否定的是合作态度或表现，不是工作能力。',COIVE+[['英语 un- + cooperative → uncooperative','不愿配合、合作困难的']],'一个人不回答合理的问题、拒绝协调时间，可以被说成 uncooperative。也可半开玩笑地说天气或设备“不配合”，不意味着它们真的有意志。','an uncooperative witness；an uncooperative attitude；remain uncooperative。','unable 是做不到；uncooperative 通常偏不愿配合。判断别人不配合之前，语境可能还需要说明其实际困难。',('The tenant remained uncooperative about arranging access for repairs.','在安排维修人员进屋这件事上，租客一直不愿配合。'),('An uncooperative printer delayed the start of the meeting.','一台不听使唤的打印机耽误了会议开始。')),
E('operationally','英 /ˌɒpəˈreɪʃənəli/；美 /ˌɑːpəˈreɪʃənəli/','在实际运行上；从操作层面；按操作性定义','换一个角度看：这件事真正运行或执行起来会怎样。','operational + -ly；可修饰可行性、准备情况，也可说明怎样把抽象概念落实为测量规则。',ION+[['英语 operational → operationally','从实际运行或具体操作的层面来说']],'technically possible 不保证 operationally practical：技术做得出，但人员、流程、时间未必安排得过来。研究中 define something operationally，则要说明到底观察或测量什么。','operationally feasible；operationally ready；define something operationally。','practically 在日常英语中还可表示“几乎”；operationally 不表示几乎，而限定为运作、执行这一方面。',('The plan is technically sound but operationally difficult.','这个计划技术上可靠，实际运作却很困难。'),('The study defines progress operationally as the number of tasks completed without help.','这项研究把“进步”操作性地定义为无需帮助就能完成的任务数量。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/operationally']),
E('inoperative','英 /ɪnˈɒpərətɪv/；美 /ɪnˈɑːpərətɪv/','不工作的；未生效的；不起作用的','本应发挥作用的环节，现在没有发挥作用。','in-“不” + operative；可以否定设备运行，也可以否定规则效力。',IVE+[['英语 in- + operative → inoperative','不运作或不起效']],'an inoperative alarm 是不工作的警报器，原因可能是故障，也可能是被停用。a clause becomes inoperative 指条款不再产生效力，不是纸面上被物理删除。','an inoperative system；remain inoperative；render a provision inoperative。','inoperable 更偏不能被操作或使用；inoperative 侧重此刻没有发挥功能，两者谈坏设备时可有重叠。',('The alarm was inoperative during the power cut.','停电期间警报器没有工作。'),('The new agreement made the old clause inoperative.','新协议使旧条款不再生效。'),sources=['https://www.etymonline.com/word/inoperative']),
E('oeuvre','/ˈɜːvrə/，亦 /ˈuːvrə/','作品；一位创作者的全部作品','把一个人多年做出的作品摊在一起，看作一个整体。','借法语 œuvre，经古法语 uevre 接拉丁 opera“工作、作品”；与 opera 同源，却经法语走出不同外形和用法。',O+[['古法语 uevre → 法语 œuvre','作品、工作'],['英语 oeuvre','正式谈作品，尤其指某位作者或艺术家的全部创作']],'评论中 the painter’s oeuvre 常是这位画家整批创作的总貌，不限于一张画。这个词语体较正式；日常说 body of work 更容易理解。法语连字 œ 在英语里常写成 oe。','the complete oeuvre；throughout her oeuvre；an artist’s oeuvre。','opus 常指一部作品或音乐编号中的作品；oeuvre 尤其常看创作者一生或一个阶段的整体作品。',('The exhibition presents works from every stage of the painter’s oeuvre.','展览呈现了这位画家各个创作阶段的作品。'),('Images of the sea recur throughout her oeuvre.','海洋意象反复出现在她的全部作品中。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/oeuvre','https://en.wiktionary.org/wiki/oeuvre#English'])
]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());family=next(r['family'] for r in m['roots'] if r['id']=='C0898');owned=set(m['owned_words'])
ROOT=[dict(id='C0898',meaning='工作；起作用；作品',core='把事做起来，也把做出来的成果看成作品',image='operate 让事情运行；operation 是一套执行过程；cooperate 是一起做；opus、opera、oeuvre 则看做成的作品。',intro='拉丁 opus 是工作或作品，属格 operis 露出 oper-。同一组材料一边发展为“做事、产生效果”，另一边保留“作品”的意思。先抓“做起来、做出来”，操作、手术、合作与歌剧就不再是四个互不相干的中文词。',forms='oper- 常见于 operate、operation；opus 保留拉丁基本形。opera 通过意大利语进入英语，oeuvre 通过法语进入；不能把二者说成现代 operate 的缩略。operation、operative、operator 等有独立借入路线，现代拆分方便理解，不代替历史。',branches=[['运行与执行','operate、operation、operator、operational、operationally、operative'],['能否发挥作用','operable、inoperable、inoperative'],['共同工作','cooperate、cooperation、cooperative、cooperatively、uncooperative'],['做成的作品','opus、opera、operatic、oeuvre']],contrasts='operatic 是歌剧的，operative 是起作用的或手术的。operable 强调能够使用，operational 常指已具备运行条件。inoperable 的医学义只限制手术途径，不能直接译成“无药可救”。',practice='把机器、公司、手术分别放进 operate 的句子，注意 operate on。再解释为什么 cooperative 可以是一个人的态度，也可以是一种组织；最后用 opus 和 oeuvre 分别谈一部作品和全部作品。',words=list(family),sources=['https://www.etymonline.com/word/operation','https://www.etymonline.com/word/opera','https://www.etymonline.com/word/operative'])]
